42  function applyCoupon(raw) {
43    const code = String(raw || '').trim().toUpperCase();
44    if (!code) {
45      state.message = 'Please enter a coupon code.';
46      return false;
47    }
48    const coupon = COUPONS[code];
49    if (!coupon) {
50      state.message = 'Invalid coupon code.';
51      return false;
52    }
53    if (coupon.type === 'fixed') {
54      if (state.coupons.includes(code)) {
55        state.message = 'Coupon already applied.';
56        return false;
57      }
58      // Fixed coupons can never exceed the order value.
59      state.fixedDiscount = Math.min(coupon.value, subtotal());
60    }
61    state.coupons.push(code);
62    state.message = 'Coupon ' + code + ' applied.';
63    return true;
64  }

66  function discountAmount() {
67    const sub = subtotal();
68    let percent = 0;
69    for (const code of state.coupons) {
70      const c = COUPONS[code];
71      if (c.type === 'percent') percent += c.value;
72    }
73    return round2((sub * percent) / 100 + state.fixedDiscount);
74  }
